    stream_api_stream_get: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description text/event-stream; each message is one `data:` JSON event. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/event-stream": {
                        /**
                         * Market State
                         * @enum {string}
                         */
                        market_state: "open" | "closed" | "holiday";
                        /** Ts */
                        ts: string;
                        /**
                         * Type
                         * @default hello
                         * @constant
                         */
                        type: "hello";
                    } | {
                        /** Fx Eur Usd */
                        fx_eur_usd?: string | null;
                        /**
                         * Market State
                         * @enum {string}
                         */
                        market_state: "open" | "closed" | "holiday";
                        /** Total Value Eur */
                        total_value_eur?: string | null;
                        /** Total Value Usd */
                        total_value_usd?: string | null;
                        /** Ts */
                        ts: string;
                        /**
                         * Type
                         * @default tick
                         * @constant
                         */
                        type: "tick";
                    } | {
                        /**
                         * Market State
                         * @enum {string}
                         */
                        market_state: "open" | "closed" | "holiday";
                        /** Ts */
                        ts: string;
                        /**
                         * Type
                         * @default refresh
                         * @constant
                         */
                        type: "refresh";
                    } | {
                        /** Fx Eur Usd */
                        fx_eur_usd?: string | null;
                        /**
                         * Market State
                         * @enum {string}
                         */
                        market_state: "open" | "closed" | "holiday";
                        /** Ts */
                        ts: string;
                        /**
                         * Type
                         * @default fx
                         * @constant
                         */
                        type: "fx";
                    };
                };
            };
        };
    };
